<?php
require __DIR__ . '/../includes/auth.php'; require_login(); require __DIR__ . '/../includes/db.php';
$pageTitle='Record mating'; $error=null; $pigs=$pdo->query("SELECT p.* FROM pigs p WHERE p.category='sow' AND p.status='active' AND NOT EXISTS (SELECT 1 FROM sow_records s WHERE s.pig_id=p.pig_id AND s.status='pregnant') ORDER BY p.tag_number")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$pigId=(int)$_POST['pig_id'];$date=$_POST['mating_date'];$check=$pdo->prepare("SELECT tag_number FROM pigs WHERE pig_id=:pig AND category='sow'");$check->execute(['pig'=>$pigId]);$pig=$check->fetch();$activeCheck=$pdo->prepare("SELECT COUNT(*) FROM sow_records WHERE pig_id=:pig AND status='pregnant'");$activeCheck->execute(['pig'=>$pigId]);if(!$pig){$error='Choose a valid sow.';}elseif($activeCheck->fetchColumn()){ $error='This sow already has an active pregnancy record.';}else{ $statement=$pdo->prepare("INSERT INTO sow_records (pig_id,mating_date,expected_farrowing_date) VALUES (:pig,:mating_date,DATE_ADD(:expected_date, INTERVAL 114 DAY))");$statement->execute(['pig'=>$pigId,'mating_date'=>$date,'expected_date'=>$date]);$expectedDate=(new DateTimeImmutable($date))->modify('+114 days')->format('Y-m-d');require __DIR__ . '/../includes/audit.php';audit_log($pdo, "Recorded mating for sow {$pig['tag_number']} (due {$expectedDate})");flash('success','Mating recorded with a 114-day countdown.');redirect('sows/index.php');}}
require __DIR__ . '/../includes/header.php';
?>
<div class="page-heading"><div><p class="eyebrow"><a class="back-button" href="index.php" aria-label="Back to sow tracker" title="Back to sow tracker"><i data-lucide="arrow-left" aria-hidden="true"></i></a>Breeding operations</p><h2>Record mating</h2></div></div><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif; ?><div class="card"><form method="post" class="row g-3"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><div class="col-md-6"><label class="form-label">Sow</label><div class="filter-select compact-form-select" data-filter-select><input type="hidden" name="pig_id" value=""><button class="filter-select-toggle" type="button" aria-haspopup="listbox" aria-expanded="false" aria-controls="mating-sow-options" data-filter-select-toggle>Choose a sow<i data-lucide="chevron-down" aria-hidden="true"></i></button><div class="filter-select-menu" id="mating-sow-options" role="listbox" hidden><button type="button" role="option" aria-selected="true" data-filter-option="">Choose a sow</button><?php foreach($pigs as $pig): ?><button type="button" role="option" aria-selected="false" data-filter-option="<?= (int)$pig['pig_id'] ?>"><?=e($pig['tag_number'])?> · <?=e($pig['pen_number'] ?: 'No pen')?></button><?php endforeach; ?></div></div></div><div class="col-md-6"><label class="form-label">Mating date<input class="form-control" type="date" name="mating_date" value="<?=date('Y-m-d')?>" required></label></div><div class="col-12"><button class="btn btn-danger primary-action" type="submit">Start countdown</button></div></form></div>
